import json,hashlib,pathlib,datetime
out=pathlib.Path('outputs/verification/fixed-scene-transition-20261025')
def read(p):return json.loads(pathlib.Path(p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.file_digest(pathlib.Path(p).open('rb'),'sha256').hexdigest()
build=read('work/scene-v2-build-receipt.json');names=['smoke-1366','campaign-1366-prefix','study-completion-1366','campaign-1920','permission-smoke-1366','permission-smoke-1920','focus-1366','focus-1920','refusal-1366','refusal-1920'];runs={n:read(out/n/'report.json') for n in names}
for n,r in runs.items():
 assert r['version_consistent'] and r['build']==build and r['ending_build']==build,n+' version mismatch'
 assert sha(out/n/'runner.cjs')==r['runner_sha256'],n+' runner mismatch'
 if n!='campaign-1366-prefix':assert r['pass'],n+' failed'
prefix=runs['campaign-1366-prefix'];assert not prefix['pass'] and len(prefix['cycles'])==6 and prefix['failure']=='Error: Movement did not work after return'
assert len(runs['study-completion-1366']['cycles'])==1 and runs['study-completion-1366']['cycles'][0]['id']=='study_chair'
assert len(runs['campaign-1920']['cycles'])==7
for cycles in [prefix['cycles']+runs['study-completion-1366']['cycles'],runs['campaign-1920']['cycles']]:
 assert sorted(c['id'] for c in cycles)==sorted(['entry_stool']*3+['sofa_middle','window_seat','dining_chair','study_chair'])
 assert sorted(c['yaw'] for c in cycles if c['id']=='entry_stool')==[0,120,240]
for n in ['permission-smoke-1366','permission-smoke-1920']:assert runs[n]['cycles'][0]['activation_before_escape']['activation'] is False
assert any(e['trusted'] and e['repeat'] and e['mode']=='EXPLORE' for e in runs['permission-smoke-1920']['returned_repeat']['events'])
assert sha('outputs/godot/playroom.gd')==build['runtime']
archive=out/'package'/build['pack'];assert sha(archive)==build['sha256']==sha(pathlib.Path('outputs/web')/build['pack'])
protected=read('work/fixed-scene-transition-20261025/protected-manifest.json');changed=[];missing=[]
for r in protected:
 p=pathlib.Path(r['path'])
 if not p.exists():missing.append(r['path'])
 elif sha(p)!=r['sha256']:changed.append({'path':r['path'],'before':r['sha256'],'after':sha(p)})
protection={'count':len(protected),'changed':changed,'missing':missing};(out/'protected-check.json').write_text(json.dumps(protection,indent=2),encoding='utf-8');assert not changed and not missing,'Protected files changed'
metrics=read(out/'transition-metrics.json');assert all(c['black_images'] for c in metrics['continuous_screencasts'])
summary={'generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Fixed-scene transition and Esc layer builder verification; owner native UI and final independent acceptance are separate','build':build,'package_archive':archive.as_posix(),'builder_validation_pass':True,'owner_native_ui':'EVIDENCE_GAP','owner_native_ui_reason':'Parent reports Computer Use stopped because current browser URL could not be reliably verified; no native input or screenshot acceptance claimed. Parent independent known-URL headless check remains separate.','core_browser_cases':14,'core_composition':{'1366':'6 accepted cycles from original false prefix + 1 same-package study completion; not a single uninterrupted passing campaign','1920':'7 completed passing cycles'},'additional_browser_cases':{'initial_smoke':1,'clean_permission_boundary':2,'real_transition_focus':2},'carrier_failed_completed_seat_attempts':1,'failed_attempt_note':'Original 1366 study return moved about94.5mm in positive X rather than required120mm; screenshot/location consistent with desk boundary, no per-slide collider trace. Negative-X completion used same180ms/120mm test and real spawn route. Original false report retained.','engine':{'build_checks':4,'seat_yaw_zoom_cases':30,'capture_denial_and_interrupted_exit_cases':2,'fade_phase_blur_lost_keyup_cases':3,'permission_scope':'explicit external native-state simulation, never browser permission proof'},'permission_boundary':'Only permission-smoke-1366/1920 establish final inactive userActivation immediately before real Escape using CDP userGesture:false exclusively after the wait. Earlier matrix activation observations were followed by Playwright evaluate and are not final permission-boundary proof.','real_repeat':'1920 clean permission smoke records a trusted initial press in SEATED and trusted repeats in STAND_UP/EXPLORE; held repeat after EXPLORE preserves capture, release plus fresh Escape pauses.','focus_observations':{str(w):{'last_submitted_phase_when_hidden_read':runs['focus-'+str(w)]['hidden']['frame']['transition_phase'],'last_submitted_alpha_when_hidden_read':runs['focus-'+str(w)]['hidden']['frame']['fade_alpha'],'hidden_dom':runs['focus-'+str(w)]['hidden']['dom']} for w in [1366,1920]},'focus_scope':'DOM and frame reads are not atomic; these are last drawn frames before/while hidden, not exact alpha at the focus-out event. Black-window interruption is engine simulation only.','capture_refusal_scope':'Actual sandbox permission errors and real retry on each resolution; recovery navigates to a new unrestricted document, not an in-place sandbox permission change. Exit capture denial is separately engine-simulated.','transition_timing':{'scope':metrics['timing_scope'],'all_trace_attempts':len(metrics['metrics']),'observed_span_ms':[min(m['transition_first_submitted_to_sit_ms'] for m in metrics['metrics']),max(m['transition_first_submitted_to_sit_ms'] for m in metrics['metrics'])],'max_submission_gap_ms':max(m['transition_render_frame_peak_ms'] for m in metrics['metrics']),'nominal_fade_ms':[150,200],'performance_acceptance':'Not a new sustained FPS or long-tour gate; old performance results unchanged.'},'continuous_capture_sets':metrics['continuous_screencasts'],'reports':{n:{'path':(out/n/'report.json').as_posix(),'sha256':sha(out/n/'report.json'),'raw_pass':r['pass'],'runner_sha256':r['runner_sha256']} for n,r in runs.items()},'protection':protection,'cleanup':'All builder browser/Node and temporary refusal servers closed; existing8767 preview retained. No commit/push/deploy. Parent independently owns any further known-URL headless check; native UI remains an evidence gap.','limitations':['Builder browser evidence is actual installed headless Chrome with Intel UHD and ?test observation bridge. Owner native foreground check remains EVIDENCE_GAP after tool URL-verification stop; parent headless evidence is separate.','Continuous JPEGs plus frame_pre_draw traces establish observed covered cuts; no claim of watching every frame as video.','Historical reports and prior performance failures were not rewritten.']}
(out/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
files={p for p in out.rglob('*') if p.is_file() and p.name not in ['source-manifest.json','review.md'] and not any(x.startswith('owner-') for x in p.relative_to(out).parts)}
for name in ['outputs/godot/playroom.gd','outputs/godot/project.godot','outputs/godot/scene_environment.gd','outputs/Verify-Camera.gd','outputs/Verify-Playroom.gd','outputs/Verify-House.gd','outputs/web/index.html','work/scene-v2-build-receipt.json','work/fixed-scene-transition-20261025/baseline/manifest.json','work/fixed-scene-transition-20261025/candidate-1/manifest.json','work/fixed-scene-transition-20261025/candidate-1/source.diff','work/fixed-scene-transition-20261025/protected-manifest.json']:files.add(pathlib.Path(name))
manifest=[{'path':p.as_posix(),'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(files)];(out/'source-manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8');print(json.dumps({'summary_sha256':sha(out/'summary.json'),'manifest_sha256':sha(out/'source-manifest.json'),'manifest_count':len(manifest),'protected_count':len(protected),'pack':build['sha256'],'runtime':build['runtime']}))
